except Exception:
    vars['today_say'] = raw
    vars['today_iso'] = raw[:10]
    vars['callback_facts'] = 'today later than now and up to 19:00, or the next business day from 10:00 to 19:00'
'''

ACCOUNT_CODE = DATE_LIB + r'''
def money(x):
    try:
        return '{:,.2f}'.format(float(x))
    except Exception:
        return str(x)
def get_products():
    P = vars.get('products')
