        deadline = addbd(today, 7)
        attempts = 2
    mon = today - TD(days=today.weekday())
    wk = [mon + TD(days=i) for i in range(5) if isbd(mon + TD(days=i))]
    a1 = max(wk) if wk else None
    if a1 is None or a1 <= today:
        nmon = mon + TD(days=7)
