import json,freya
r=json.load(open('results/run2.json'))
rows = r if isinstance(r,list) else r.get('rows',r)
for x in rows:
    if x.get('id') in ('PUB-10','PUB-04'):
        c=freya.get_call(x['call_id'])
        print('=====',x['id'])
        for m in c['messages']:
            t=m.get('message','')
            if m['role'] in('user','assistant'): print(m['role'].upper(), t[:300])
            elif 'function_call' in t or 'node_enter' in t: print('  SYS', t[:400])
EOF

